    } else if (selected == 13) {
        static_cast<void>(audio::PlaySe_52C450(51, 320));
        return 3;
    } else if (selected < 0) {
        return 0;
    }
    static_cast<void>(audio::PlaySe_52C450(51, 320));
    return 1;
}

